const slugs=['milk','denim-blue','sand-honey','ice-blue','muted-wine','graphite'];
const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('#mobile-nav').hidden=expanded;});
document.querySelectorAll('header nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page');});
function paletteCard(i){return `<a class="card" href="/${slugs[i]}.html"><div class="card-top"><span>0${i+1} / ${colors[i].ru.toUpperCase()}</span><span>EN + RU</span></div>${board(1,i,'palette'+i)}<div class="card-bottom"><strong>${colors[i].name}</strong><span aria-hidden="true">→</span></div></a>`;}
const catalog=document.querySelector('#catalog-grid');if(catalog){const draw=filter=>{catalog.innerHTML=colors.map((_,i)=>i).filter(i=>filter==='all'||(filter==='light'?[0,2,3].includes(i):[1,4,5].includes(i))).map(paletteCard).join('');};draw('all');document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});draw(b.dataset.filter);}));}
document.querySelectorAll('[data-product]').forEach(el=>{el.innerHTML=board(1,Number(el.dataset.product),'product');});
function getSaved(){try{const data=JSON.parse(localStorage.getItem('form-builds')||'[]');return Array.isArray(data)?data.filter(b=>Number.isInteger(b.c)&&b.c>=0&&b.c<cases.length&&Number.isInteger(b.k)&&b.k>=0&&b.k<colors.length).slice(0,24):[];}catch{return [];}}
const config=document.querySelector('.config-controls');if(config){const tools=document.createElement('div');tools.className='build-tools';tools.innerHTML='<button id="keep-build" class="secondary">Keep in saved builds</button><button id="share-build" class="secondary">Copy combination link</button>';config.insertBefore(tools,config.querySelector('.fine'));document.querySelector('#keep-build').addEventListener('click',()=>{const saved=getSaved();if(!saved.some(b=>b.c===selectedCase&&b.k===selectedKey))saved.push({c:selectedCase,k:selectedKey});try{localStorage.setItem('form-builds',JSON.stringify(saved));document.querySelector('#status').textContent='Saved to this browser. Find it in Saved builds.';}catch{document.querySelector('#status').textContent='Browser storage is unavailable. Download a build card instead.';}});document.querySelector('#share-build').addEventListener('click',async()=>{const url=new URL('/configure.html',location.origin);url.searchParams.set('case',selectedCase);url.searchParams.set('color',selectedKey);try{await navigator.clipboard.writeText(url.href);document.querySelector('#status').textContent='Combination link copied.';}catch{document.querySelector('#status').textContent='Copy this link: '+url.href;}});}
const savedGrid=document.querySelector('#saved-grid');if(savedGrid){function drawSaved(){const saved=getSaved();document.querySelector('#saved-status').textContent=saved.length?`${saved.length} saved combination${saved.length===1?'':'s'}.`:'No favorites yet. Explore the configurator to save your first combination.';savedGrid.innerHTML=saved.length?saved.map((b,i)=>`<article class="card"><div class="card-top"><span>YOUR BUILD / ${String(i+1).padStart(2,'0')}</span></div>${board(b.c,b.k,'saved'+i)}<h3>${colors[b.k].name} / ${cases[b.c].name}</h3><div class="build-tools"><a class="secondary" href="/configure.html?case=${b.c}&amp;color=${b.k}">Open build →</a><button class="secondary remove-build" data-c="${b.c}" data-k="${b.k}" aria-label="Remove ${colors[b.k].name} on ${cases[b.c].name}">Remove</button></div></article>`).join(''):'<a class="pill" href="/configure.html">Create your first build →</a>';}
 savedGrid.addEventListener('click',e=>{const b=e.target.closest('.remove-build');if(!b)return;try{localStorage.setItem('form-builds',JSON.stringify(getSaved().filter(x=>x.c!==Number(b.dataset.c)||x.k!==Number(b.dataset.k))));drawSaved();}catch{document.querySelector('#saved-status').textContent='Unable to update browser storage.';}});drawSaved();}
